const msg = $input.item.json.message || {};

const chatId = String(msg.chat?.id || msg.from?.id || '');
const text = (msg.text || '').trim();
const textLower = text.toLowerCase();
const name = msg.from?.first_name || 'there';

// Return empty array = stop silently (photo, sticker, no text, no chatId)
if (!chatId || !text) return [];

const searchPrefixes = ['search ', 'find ', 'show ', 'scrape ', 'look for ', 'clone '];
const isSearch = searchPrefixes.some(p => textLower.startsWith(p));
const isNumber = /^([1-9]|10)$/.test(text.trim());
const helpWords = ['help', 'start', '/start', '/help', 'hi', 'hello', 'hey', '?', 'menu', 'begin'];
const isHelp = helpWords.some(w => textLower === w || textLower.startsWith(w + ' '));

let query = '';
if (isSearch) {
  for (const p of searchPrefixes) {
    if (textLower.startsWith(p)) { query = textLower.replace(p, '').trim(); break; }
  }
}

return [{ json: { chatId, text: textLower, name, isSearch, isNumber, isHelp, query } }];

const resp = $input.item.json;
const orig = $('Parse Message').item.json;

const raw = resp?.content?.[0]?.text || '[]';
let sites = [];
try {
  const m = raw.match(/\[[\s\S]*\]/);
  if (m) sites = JSON.parse(m[0]);
} catch (e) {}
sites = sites.slice(0, 10);

if (!sites.length) {
  return [{ json: {
    chatId: orig.chatId,
    query: orig.query,
    sites: [],
    sitesJson: '[]',
    replyText: `❌ Couldn't find sites for "${orig.query}". Try a different category!`
  }}];
}

let msg = `🔍 *Top ${sites.length} sites for "${orig.query}":*\n\n`;
sites.forEach(s => {
  msg += `*${s.rank}.* [${s.name}](${s.url})\n_${s.description}_\n\n`;
});
msg += `Reply with a number *1-${sites.length}* to start scraping that site ✅`;

return [{ json: {
  chatId: orig.chatId,
  query: orig.query,
  sites,
  sitesJson: JSON.stringify(sites),
  replyText: msg
}}];

const d = $input.item.json;
const state = $getWorkflowStaticData('global');
if (d.sites && d.sites.length) {
  state[d.chatId] = JSON.stringify({
    State: 'waiting_selection',
    Category: d.query,
    Results: d.sitesJson,
    UpdatedAt: new Date().toISOString()
  });
}
console.log('Saved state for chatId:', d.chatId, 'sites:', d.sites ? d.sites.length : 0);
return [{ json: d }];

const state = $getWorkflowStaticData('global');
const orig = $('Parse Message').item.json;
const raw = state[orig.chatId];
let row = {};
if (raw) {
  try { row = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { row = {}; }
}
console.log('Got state for chatId:', orig.chatId, '→', row.State || 'none');
return [{ json: { ...row, chatId: orig.chatId, text: orig.text } }];

const row = $input.item.json;
const orig = $('Parse Message').item.json;

const num = parseInt(orig.text.trim());
let sites = [];
try { sites = JSON.parse(row.Results || '[]'); } catch (e) {}

if (!sites.length) {
  return [{ json: { _error: true, chatId: orig.chatId, errText: '❌ No active search. Send *search [category]* first!' } }];
}
if (num < 1 || num > sites.length) {
  return [{ json: { _error: true, chatId: orig.chatId, errText: `❌ Send a number between 1 and ${sites.length}.` } }];
}

const chosen = sites[num - 1];
return [{ json: {
  _error: false,
  chatId: orig.chatId,
  targetUrl: chosen.url,
  siteName: chosen.name,
  category: row.Category || chosen.name,
  confirmText: `✅ Starting scrape of *${chosen.name}*\n${chosen.url}\n\n⏳ This takes 5-10 minutes. I'll ping you when done!`
}}];
